# GF(2) linear CA on torus: eigenvalue machinery
import itertools, functools

ORBS = [(a,b) for a in range(5) for b in range(a+1)]  # 15 orbits, (a,b) with 0<=b<=a<=4

def orbit(a,b):
    s=set()
    for sa in (1,-1):
        for sb in (1,-1):
            s.add((sa*a,sb*b)); s.add((sa*b,sb*a))
    return s

def rule_support(rid):
    # rule id: bitmask over ORBS? We need to figure out the id convention. We'll test later.
    S=set()
    for i,(a,b) in enumerate(ORBS):
        if rid>>i &1: S|=orbit(a,b)
    return frozenset(S)

# Laurent polys as dict {(a,b):1} over GF(2) -> represent as frozenset of exponent pairs
def pmul(P,Q):
    d={}
    for (a,b) in P:
        for (c,e) in Q:
            k=(a+c,b+e); d[k]=d.get(k,0)^1
    return frozenset(k for k,v in d.items() if v)
def padd(P,Q): return frozenset(set(P)^set(Q))
def ppow(P,n):
    R=frozenset([(0,0)])
    for _ in range(n): R=pmul(R,P)
    return R
def pdil(P,n): return frozenset((n*a,n*b) for (a,b) in P)
def preduce(P,m):
    d={}
    for (a,b) in P:
        k=(a%m,b%m); d[k]=d.get(k,0)^1
    return frozenset(k for k,v in d.items() if v)

# GF(2)[x] as ints
def gmul(a,b):
    r=0
    while b:
        if b&1: r^=a
        a<<=1; b>>=1
    return r
def gmod(a,mod):
    dm=mod.bit_length()-1
    while a.bit_length()-1>=dm:
        a^=mod<<(a.bit_length()-1-dm)
    return a
def gmulmod(a,b,mod): return gmod(gmul(a,b),mod)
def gpowmod(a,e,mod):
    r=1
    while e:
        if e&1: r=gmulmod(r,a,mod)
        a=gmulmod(a,a,mod); e>>=1
    return r

class CycField:
    """GF(2)[x]/(Phi_m(x)) when 2 is primitive mod m (Phi_m irreducible). zeta = x."""
    def __init__(self,m):
        self.m=m
        self.phi=(1<<m)-1  # x^(m-1)+...+1  = (x^m-1)/(x-1)  as bits: all ones m bits -> 1+x+...+x^(m-1)
        self.d=m-1
        self.order=(1<<self.d)-1
    def eig(self,P,j,k):
        # f(zeta^j, zeta^k) = sum x^(ja+kb) mod x^m-1, then reduce mod phi
        v=0
        for (a,b) in P:
            v^=1<<((j*a+k*b)%self.m)
        return gmod(v,self.phi)
    def is_qth_power(self,lam,q):
        assert self.order%q==0
        return gpowmod(lam,self.order//q,self.phi)==1
    def mult_order(self,lam):
        # order divides 2^d-1
        from sympy import factorint
        n=self.order
        for p,e in factorint(n).items():
            for _ in range(e):
                if gpowmod(lam,n//p,self.phi)==1: n//=p
                else: break
        return n

def classes(m):
    """character classes (j,k) up to the lattice symmetry group (8 elements) -- (j,k)!=(0,0)"""
    seen=set(); reps=[]
    for j in range(m):
        for k in range(m):
            if (j,k)==(0,0) or (j,k) in seen: continue
            orb=set()
            for sa in (1,-1):
                for sb in (1,-1):
                    orb.add(((sa*j)%m,(sb*k)%m)); orb.add(((sa*k)%m,(sb*j)%m))
            seen|=orb; reps.append((j,k))
    return reps

def frob_classes(m):
    """classes under lattice symmetry AND (j,k)->(2j,2k) (Frobenius) : eigenvalues at these are Galois conjugate"""
    seen=set(); reps=[]
    for j in range(m):
        for k in range(m):
            if (j,k)==(0,0) or (j,k) in seen: continue
            orb=set(); stack=[(j,k)]
            while stack:
                (u,v)=stack.pop()
                for sa in (1,-1):
                    for sb in (1,-1):
                        for p in [((sa*u)%m,(sb*v)%m),((sa*v)%m,(sb*u)%m)]:
                            if p not in orb:
                                orb.add(p); stack.append(((2*p[0])%m,(2*p[1])%m))
            seen|=orb; reps.append(((j,k),len(orb)))
    return reps

