28944:[(2,1),(3,2),(4,2),(4,3),(4,4)],
}
def rule_from_orbits(orbs):
    S=set()
    for (a,b) in orbs: S|=orbit(a,b)
    return frozenset(S)

# Bivariate factorisation over GF(2) via Kronecker substitution + recombination
from sympy import symbols, Poly, factor_list, GF
from itertools import combinations
X=symbols('X')

def to_poly(P):
    """Laurent set -> (dict poly with nonneg exps, shift)"""
    ax=min(a for a,b in P); by=min(b for a,b in P)
    return frozenset((a-ax,b-by) for a,b in P), (ax,by)

def kron(P,N):
    v=0
    for a,b in P: v^=1<<(a+b*N)
    return v
def unkron(v,N):
    P=set(); i=0
    while v:
        if v&1: P.add((i%N,i//N))
        v>>=1; i+=1
    return frozenset(P)
def int_to_sympoly(v):
    coeffs=[]
    n=v.bit_length()
    return Poly([ (v>>(n-1-i))&1 for i in range(n)], X, modulus=2)
def sympoly_to_int(p):
    v=0
    for (e,),c in p.terms():
        if int(c)%2: v^=1<<e
    return v

def pmul(P,Q):
    d={}
    for (a,b) in P:
        for (c,e) in Q:
            k=(a+c,b+e); d[k]=d.get(k,0)^1
    return frozenset(k for k,v in d.items() if v)

def pdivides(G,F):
    """exact division of bivariate polys over GF(2) (nonneg exps). returns quotient or None"""
    # multivariate division using lex order on (b,a)
    F=set(F); Q=set()
    g_lead=max(G, key=lambda t:(t[1],t[0]))
    while F:
        f_lead=max(F, key=lambda t:(t[1],t[0]))
        da=f_lead[0]-g_lead[0]; db=f_lead[1]-g_lead[1]
        if da<0 or db<0: return None
        Q.add((da,db))
        for (a,b) in G:
            k=(a+da,b+db)
            if k in F: F.remove(k)
            else: F.add(k)
    return frozenset(Q)

def factor_bivariate(P):
    """returns list of (factor(frozenset poly, nonneg exps), multiplicity); P must have nonneg exps and nonzero const? not needed"""
    P0,shift=to_poly(P)
    degx=max(a for a,b in P0)
    # remove content in x,y monomials: handled by shift
    N=2*degx+2
    v=kron(P0,N)
    fl=factor_list(int_to_sympoly(v))[1]
    ufs=[]
    for p,e in fl:
        ufs+= [sympoly_to_int(p)]*e
    # recombination
    result=[]
    rem=P0
    pool=ufs[:]
    found=True
    while len(pool)>0:
        found=False
        for r in range(1,len(pool)+1):
            for idx in combinations(range(len(pool)),r):
                v=1
                for i in idx:
                    v2=pool[i]
                    # multiply
                    acc=0;a=v;b=v2
                    while b:
                        if b&1: acc^=a
                        a<<=1;b>>=1
                    v=acc
                cand=unkron(v,N)
                if max(a for a,b in cand)>=N: continue
                # candidate must be a genuine bivariate poly with x-degree < N; check division
                q=pdivides(cand,rem)
                if q is not None:
                    result.append(cand); rem=q
                    pool=[pool[i] for i in range(len(pool)) if i not in idx]
                    found=True; break
            if found: break
        if not found:
            raise RuntimeError("recombination failed")
    assert rem==frozenset([(0,0)]), rem
    # group
    from collections import Counter
    c=Counter(result)
    return list(c.items()), shift

def pstr(P):
    terms=sorted(P,key=lambda t:(t[0],t[1]))
    out=[]
    for a,b in terms:
        s=[]
        if a: s.append("x^%d"%a if a!=1 else "x")
        if b: s.append("y^%d"%b if b!=1 else "y")
        out.append("*".join(s) if s else "1")
    return "+".join(out)

